function in = sf_inputs()
%SF_INPUTS  Inputs and assumptions of step 3.7: fault tree, FMEA, critical parts, damage tolerance, fire.
%   in = sf_inputs()
%
%   Requirement IDs are in the comments; every assumed rate, material
%   constant and size is marked TBR with its source. Units: h, mm, N, MPa,
%   MPa sqrt(m), degC unless noted.
%   Source: Phase 3 report, Section 3.7.

% Service and maintenance basis (STR-05, A-05, A-06)
in.life_h = 20000;                          % h, design service life (STR-05)
in.tbo_h = 4000;                            % h, overhaul interval (STR-05)
in.mission_h = 30;                          % h, A-05 mission
in.cyc_per_h = 1;                           % flight cycles per hour used for life counting: a 1 h sortie bound for any
                                            % mission mix (TBR); A-05 alone would give 1/30
in.target_h = 1e-8;                         % per engine flight hour, hazardous engine effect (SAF-01, CS-E 510 (a)(3))

% D1 Fault tree of propeller release (SAF-01). Load paths of steps 2.5 and 3.1 (part numbers of manufacturing/bom_v1.csv):
%   Pusher layout: positive thrust pushes the propeller toward the gearbox (-z, push-in, through the KM24 nut); the
%   drag of a windmilling or feathered propeller and negative thrust act aft (+z, LD-04 pull-out).
%   primary   pull-out (LD-04, +z): propeller -> flange P115 (4340, PIF-01 placeholder) and its bolts -> carrier with
%             the propeller shaft P103 -> the P103 shoulder on the inboard face of the QJ1024 inner ring (z 446; part of
%             the critical part P103) -> QJ1024 bearing -> titanium bearing housing P111 -> its bolts S604 -> planetary
%             case nose -> case flange -> engine mounts (ICD-24). The KM24 nut P112 (z 474-494) sits outboard of the
%             QJ1024 (z 446-474) and carries only the push-in thrust: it is not in the release tree (FMEA FM24)
%   standby 1 Ti-6Al-4V retention tube P114 inside the shaft, z 112 to 712: from the carrier front plate to an anchor
%             in the propeller hub 162 mm past the flange face (PIF-01 note, TBD with the propeller maker); holds the
%             propeller if the shaft breaks outboard of the QJ bearing, or if the flange P115, its joint to P103 or the
%             flange bolts fail (no load in normal running: latent)
%   standby 2 axial catcher lip, part of the nose cover P116 (envelope in.ft.lip): holds the P103 collar if the
%             QJ1024 bearing loses its axial location (no load in normal running: latent). P116 is bolted to the front
%             face of P111, so P111 with its bolts S604 is common to both paths (C2 and M1 stay single items)
%   After a shaft or flange failure (E1, E6) the tube anchors carry axial load only, no torque: the break shows as an
%   Np/Nr mismatch (CTL-02) or a torque collapse, the FADEC shuts the engine down and the propeller feathers; push-in
%   goes through the contact of the fracture faces, and the pull-out drag of the feathered or windmilling propeller
%   goes through the tube for the rest of the flight (SAF-04), in.ft.tube. A QJ1024 axial loss (E4) leaves the drive
%   chain intact (no Np/Nr or torque cue): push-in goes onto the NJ1024 standby, the thermocouples alert and the limp
%   mode holds the thrust at the NJ rating to a powered landing; the lip carries the pull-out transients and, after an
%   NJ failure, the seal crush, the E7 shutdown and feather, the run-down and the feathered drag (sf_qj)
% type: 'active' (rate per hour; exactly one per quantified cut set), 'weibull' (active, with a hazard rising as
% t^(beta-1) and renewed at the inspection interval: mean rate H(T) / T, the cumulative hazard per hour), 'latent'
% (rate per hour, found at the inspection interval T: failed with probability lambda t + q_d at time t since the
% inspection, q_d the demand failure on engagement), 'demand' (fails with probability q_d when the cut set is
% demanded), 'critical' (CS-E 515 critical part: a single failure with a hazardous effect that relies on CS-E 515
% integrity, not quantified under CS-E 510(c); the CS-E 510(a)(2) instances), 'multi' (multiple fasteners:
% qualitative, CS-E 510(a)(3) basis in the event text)
ev = @(id, type, rate, qd, en, tr, src) struct('id', id, 'type', type, 'rate', rate, 'qd', qd, 'en', en, 'tr', tr, ...
                                            'src', src);
in.ft.ev = [ ...
  ev('E1', 'active', 1e-7, 0, 'Propeller shaft P103 fracture outboard of the QJ bearing', ...
     'Pervane mili P103''ün QJ yatağının dışında kırılması', ...
     'TBR: a pessimistic residual rate for a CS-E 515 critical part (integrity from D3 / D4), quantified only to size the standby path'), ...
  ev('E6', 'active', 1e-6, 0, 'Flange P115, its joint to P103 or the flange bolts fail', ...
     'Flanş P115, P103 ile bağlantısı veya flanş cıvataları hasarı', ...
     'TBR: a separate 4340 flange (PIF-01 placeholder) with a bolted or splined joint to P103; not a critical part (D3)'), ...
  ev('E2', 'latent', 1e-6, 1e-4, 'Retention tube P114 already broken or fails on engagement', ...
     'Tutma tüpü P114 önceden kırık veya devreye girerken kırılır', ...
     'TBR: unloaded Ti-6Al-4V tube, failure from a defect, installation damage or corrosion; q_d for the shock load on engagement (above the static ultimate check of step 2.5)'), ...
  ev('E4', 'weibull', NaN, 0, 'QJ1024 bearing failure with loss of axial location (wear-out)', ...
     'QJ1024 yatağının eksenel konumu kaybettiren hasarı (yorulma)', ...
     'ISO 281 Weibull slope 3/2 on the step 2.5 L10m, replaced at TBO; share leading to loss of axial location TBR'), ...
  ev('E7', 'active', NaN, 0, 'Total loss of oil, then QJ1024 seizure or axial failure under thrust', ...
     'Tüm yağın kaybı, ardından itki altında QJ1024 sıkışması veya eksenel hasarı', ...
     'dependent cause (FMEA FM37, FM43, FM44, FM45, FM57, FM61): lambda_oil x p, TBR (in.ft.oil)'), ...
  ev('E5', 'latent', 1e-6, 1e-3, 'Lip path already failed (catcher lip, nose cover P116, its fasteners) or fails on engagement', ...
     'Dudak yolu önceden hasarlı (yakalama dudağı, burun kapağı P116, cıvataları) veya devreye girerken hasarlanır', ...
     'TBR: unloaded lip, cover and collar, damage from assembly, a lost or loose fastener, a prior bearing event, the air-side causes on the dry side of the face seal (corrosion, sand, ice, coating build-up in the gap); q_d as it catches a rotating collar'), ...
  ev('R4', 'demand', NaN, NaN, 'Lip fails by rubbing before the shutdown (QJ1024 wear-out, negative thrust)', ...
     'Dudak kapatmadan önce sürtünmeyle hasarlanır (QJ1024 yorulması, negatif itki)', ...
     'sf_lip: share of flight at negative thrust x share of QJ1024 axial losses not shut down on the ODM / chip alert first, plus a residual (TBR)'), ...
  ev('R7', 'demand', NaN, NaN, 'Lip fails by rubbing in the run-down to feathered (oil loss)', ...
     'Dudak tüylenene kadar yavaşlamada sürtünmeyle hasarlanır (yağ kaybı)', ...
     'sf_lip: the run-down rub heats the lip below its capability; residual (TBR)'), ...
  ev('CC1', 'demand', NaN, 1e-4, 'The same propeller-installation error also leaves the tube nut P114 loose', ...
     'Aynı pervane montaj hatası tüp somununu P114 de gevşek bırakır', ...
     'common cause of E6 and E2 (tube nut and flange bolts made up at one installation): 0.01 shared error x 0.01 miss, the propeller installation (flange bolts, tube nut P114 and its lock) being an ICA maintenance task with an independent inspection (ICA-05, CS-E 510(e)(1)), TBR'), ...
  ev('E8', 'active', 1e-7, 0, 'QJ pull-out shoulder ring on P103 (or its groove) fails', ...
     'P103 üzerindeki QJ çekme omuz halkası (veya kanalı) hasarı', ...
     'CS-E 515 critical part (separate shoulder ring P117, split ring in a groove with a retaining sleeve): rate basis of D1 for critical parts; the lip then catches the collar'), ...
  ev('C2', 'critical', NaN, 0, 'Bearing housing P111 fracture', 'Yatak gövdesi P111 kırılması', ...
     'CS-E 515 critical part (D3, D4), not quantified under CS-E 510(c) (a CS-E 510(a)(2) instance); it carries both the primary path and the lip path (P116 bolted to its front face)'), ...
  ev('C3', 'critical', NaN, 0, 'Planetary case nose or mount flange fracture', ...
     'Planet gövdesi burnu veya bağlantı flanşı kırılması', ...
     'CS-E 515 critical part (D3, D4), not quantified under CS-E 510(c) (a CS-E 510(a)(2) instance)'), ...
  ev('M1', 'multi', NaN, 0, 'Bolted joints in the load path (P111 to nose, mounts): all bolts of a joint', ...
     'Yük yolundaki cıvatalı bağlantılar (P111-burun, bağlantılar): bir bağlantının tüm cıvataları', ...
     'CS-E 510(a)(3) qualitative basis: multiple fasteners, one bolt lost is not hazardous; the causes that could act on all bolts of a joint are maintenance error after a module change, handling damage and corrosion, covered by VDI 2230 preload and locking and by the reassembly checks (torque, locking, witness marks) on the engine-manual list, CS-E 510(e)(1) (safety/ica_items_v1.csv)')];
% QJ1024 axial-loss rate (E4): mean hazard over one TBO of a Weibull life with slope 3/2 (the ISO 281 life
% modification for reliability) through the step 2.5 mission L10m; share of failures that lose axial location
in.ft.qj = struct('L10m', 3.50e4, 'slope', 1.5, 'f_axial', 0.01);   % h (step 2.5), -, - (TBR)
% E7: total loss of oil (sum over FM37 pump, FM43 tubes, FM44 hoses, FM45 tank, FM57 pump quill, TBR) and the
% probability p_qj that the QJ1024 then loses its axial location under pull-out, derived in sf_lip over three
% phases: (i) mist run under positive thrust (push-in on the KM24 nut: no release contribution); (ii) shutdown and
% run-down until feathered (pull-out from the windmilling drag on a QJ1024 that still turns, mist-fed by LUB-07; it
% fails only if the mist does not reach it, q_nomist, within t_dry of dry running); (iii) feathered for the rest of
% the flight (pull-out from the feathered drag on a stopped or slowly turning QJ1024, far below its static capacity,
% q_static). The PCU is fed from the RGB supply, so the loss of oil also removes the pitch-oil pressure and the
% counterweights feather the propeller (G2): t_feather from the loss of pitch pressure. All TBR
in.ft.oil = struct('lam', 1e-5, 'p_qj', 0.01, 't_mist', 360, 'F_push', 4.5e3, 't_feather', 6, 't_dry', 60, ...
    'q_nomist', 0.01, 'q_static', 1e-3);
% F_push: positive thrust in the mist run at 75% MCP [N] (TBR); t_feather: loss of pitch pressure to feathered [s];
% t_dry: dry running before the QJ1024 loses its axial location [s]
% catcher lip and nose cover P116 (Ti-6Al-4V, new part, BOM and CAD in 3.9): [r z] envelope of the cover in case
% coordinates [mm] (a bolted skirt r 84-94 on the P111 front face at z 512 and a lip disc reaching in to r 66 from
% z 516.5, its thickness from sf_lip), the P103 collar it catches (r 60-72, z 512-516, 0.40-0.60 mm gap, step 3.8
% E3c), fasteners, masses [kg] (collar and fasteners TBR; cover from sf_lip, at most m_cover_max)
in.ft.lip = struct('part', 'RGB-P116', 'rz', [84 512; 94 512; 94 519; 66 519; 66 516.5; 84 516.5], ...
    'collar_rz', [60 512; 72 512; 72 516; 60 516], 'fasteners', '8 x M5 x 16 A286 on PCD 178 into P111 (S613, with inserts, locked)', ...
    'm_cover_max', 0.30, 'm_collar', 0.16, 'm_fast', 0.04, 'attach', 'P111');
in.ft.lip.geom = struct('r_in', 66, 'r_out', 94, 'r_root', 84, 'r_load', 69, 'h_skirt', 7, 'n_bolt', 8, 'd_hole', 5.5, ...
    't_min', 2.0, 'rf_ult', 1.15, 'rho', 4.43e-6, 'Fty', 827, 'Ftu', 896, ...
    'bolt', struct('As', 14.2, 'prying', 1.3, 'Fty', 655, 'Ftu', 965));
% lip disc between the skirt inner edge r_root and the collar contact r_load; Ti-6Al-4V annealed minima [MPa];
% bolts M5 A286 (AMS 5737 minima, stress area 14.2 mm2, prying factor TBR)
in.ft.lip.rub = struct('mu', 0.4, 'n0', 1700, 'n_f', 0.05, 'F_wm', 5e3, 'F_f', 0.5e3, 't_feather', 6, 'F_neg', 2e3, ...
    'T0', 120, 'T_ref', 400, 'ky', 0.6, 'T_max', 450, 'steel', [42 7850 475], 'ti', [6.7 4430 526], ...
    'f_neg', 0.1, 'c_det', 0.9, 'q_resid', 1e-3);
% mu: dry steel on titanium; n0, n_f: propeller speed at the shutdown and feathered [rpm, share]; F_wm, F_f: drag of
% the windmilling propeller at the start of the run-down and feathered [N] (TBR, propeller data awaited); F_neg:
% negative thrust in a flight-idle descent [N] (TBR); T0: lip at the oil-wetted nose [degC]; yield of Ti-6Al-4V
% down to ky x the room-temperature value at T_ref, T_max the service limit of the lip [degC]; [k rho c] of the
% 4340 collar and the Ti lip; f_neg: share of the flight at negative thrust; c_det: share of QJ1024 wear-out axial
% losses shut down on the ODM / chip alert before the first negative-thrust phase; q_resid: residual (all TBR)
in.ft.sys06 = struct('base', 109.24, 'thread', 0.18, 'limit', 110);   % kg: roll-up after 3.6, the 95 mm bore
                                                                    % option of D4, the 110 kg TBR
% G1b QJ1024 axial-loss follow-up (design decisions, delegated by Hamit), sf_qj:
% thrust floor: in flight the FADEC holds a positive thrust floor above the gust and manoeuvre swings (no flight-idle
% negative thrust, beta or windmilling in flight; descents use drag devices, ICD-38, owner aircraft); swings [N] TBR
% (gust: thrust change with a 15 m/s vertical gust at 150 kt, manoeuvre: the n_z 2.5 pull-up); f_neg: share of the
% flight with a pull-out transient below zero thrust (engine transients only, TBR)
in.qj = struct('swing_gust', 0.6e3, 'swing_man', 0.5e3, 'margin', 0.4e3, 'f_neg', 1e-3);
% NJ1024 push-in standby (outer NU1024 at z 413 becomes an NJ1024, inner-ring rib outboard): SKF axial load capacity
% of a cylindrical roller bearing F_ap = k1 C0 1e4 / (n (d + D)) - k2 Fr [N, C0 N, n rpm, d D mm], k1 1.5 continuous,
% 3 brief (oil), k2 0.15, Fa / Fr <= 0.5; f_kappa: derating for the kappa 0.3-0.5 film (TBR); radial load at the
% 279 mm CAD span; directed jet on the rib
in.qj.nj = struct('C0', 166e3, 'n', 1700, 'd', 120, 'D', 180, 'k1', 1.5, 'k1_brief', 3, 'k2', 0.15, 'Fr', 8.6e3, ...
    'f_kappa', 0.85, 'band', 0.42, 'margin', 0.1, 'seal', 2.0);
% band: push-in band edge at the cold extreme with 20 kN (QJ play C2, deflections, thermal, 3.8 E3c basis, TBR) [mm];
% end play = band + margin, against the 2 mm seal contact
% limp mode on the thermocouple alert (two on the NJ outer ring, one in the P116 skirt; annunciation and limp only,
% no automatic shutdown, no detection credit): thrust capped at the NJ continuous rating, the floor kept, return and
% land powered. Probabilities given a QJ1024 axial loss (TBR): p_tc the share of losses in take-off and climb (A-05
% step 1/30) where the push-in exceeds the NJ brief rating; p_limp the NJ failing during the limp period
in.qj.p_tc = 1 / 30;  in.qj.p_limp = 0.05;
% E7 phase (i): a QJ1024 axial loss in the 360 s mist run at 4.5 kN on the mist-fed NJ (TBR)
in.qj.p_mist = 0.01;
% branches of R4 (lip fails before landing given E4): q_trans (pull-out transients only, NJ holding), q_wear (the
% feathered drag until landing after the run-down, wear included), q_cw the SAF-04 feather-failure branch (the
% counterweight feathering unavailability of D1b, windmilling at governed speed: the lip fails)
in.qj.q_trans = 1e-3;  in.qj.q_wear = 1e-3;
in.qj.f_axial_basis = 'f_axial 0.01: the share of QJ1024 failures (spall, cage) that lose the axial location before the ODM / chip trend leads to its removal (TBR, engineering judgement; no detection credit is taken for the R4 terms)';
% separate parts on P103 (decision 4): the QJ pull-out shoulder ring (split ring in a shaft groove with a retaining
% sleeve, z 441-446, CS-E 515: it carries the primary pull-out) and the collar (shrink collar, z 512-516, lip path);
% masses [kg] and the G1b mass changes for SYS-06 (TBR, 3.9)
in.qj.mass = struct('shoulder_ring', 0.25, 'sleeve', 0.05, 'shoulder_removed', -0.20, 'nj_liner_flange', 0.05, ...
    'qj_retainer', 0.05, 'spacer', 0.02, 'thermocouples', 0.08, 'hub_relief', -0.10, 'lip_resize', 0);
in.qj.offsets = {'P115 flange scallops between the bolt holes (3.9; flange bending margin to be kept >= 1.5)', -0.15; ...
                 'P111 pockets in the flange plate between the S604 bolts (3.9; fillet stress margin kept)', -0.10};
% lip thermal model (sf_lip): a 2-D r-z model of the lip and the collar, T0 on the dry side of the face seal (between
% the nacelle air and the P111 front face) [degC]; Ti-6Al-4V short-time yield against temperature [degC MPa] (TBR,
% MMPDS trend), the service limit for wear
in.ft.lip.thermal = struct('T0', 142, 'dr', 0.5e-3, 'nz', 4, 'collar_h', 4e-3, 'dt', 1e-3, ...
    'sy_T', [20 827; 200 690; 300 620; 400 560; 500 500; 600 400; 700 250; 800 120; 900 50]);
% retention tube check for the post-failure phase: Ti-6Al-4V 90/80 (AMS 4928 annealed minima F_ty 827, F_tu 896 MPa);
% axial load: the pull-out drag of the windmilling or feathered propeller for the rest of the flight goes through the
% tube, bounded by LD-04 (20 kN, x1.5 ultimate); push-in goes through the contact of the fracture faces, not the tube;
% a bound with the propeller weight at n_z 2.5 and the gyroscopic moment on the tube as well (if the broken stub is
% not held by the bore) [N, N m, MPa]
in.ft.tube = struct('D', 90, 'd', 80, 'Fty', 827, 'Ftu', 896, 'F_lim', 20e3, 'fu', 1.5, 'M_w', 2.5 * 76.4 * 9.81 * 0.25, ...
    'M_gyro', 7190);
in.ft.life = in.life_h;                     % h, exposure of the standby paths if never inspected (ALI basis)
in.ft.T_insp = in.tbo_h;                    % h, inspection interval of the standby paths (TBO; a check between TBOs
                                            % is an option only, not taken)
in.ft.band = 1e-7;                          % per engine flight hour, upper end of the extremely remote band (sum)
% minimal cut sets: events joined by AND; single-event sets are critical parts or multi-fastener joints
in.ft.cuts = {{'E1', 'E2'}, {'E6', 'E2'}, {'E6', 'CC1'}, {'E4', 'E5'}, {'E4', 'R4'}, {'E7', 'E5'}, {'E7', 'R7'}, ...
              {'E8', 'E5'}, {'E8', 'R4'}, {'C2'}, {'C3'}, {'M1'}};
% sensitivity, one at a time: every assumed rate and q_d x10, and E4 at an all-causes rate (main-shaft bearing
% failures 1e-5 per hour x 0.1 not caught by the chip detector, oil debris monitor or HUMS)
in.ft.sens = {'E1', 'rate', 10; 'E6', 'rate', 10; 'E2', 'rate', 10; 'E7', 'rate', 10; 'E5', 'rate', 10; ...
              'E2', 'qd', 10; 'E5', 'qd', 10; 'CC1', 'qd', 10; 'R4', 'qd', 10; 'E4', 'set', 1e-6; 'f_neg', 'qj', 10; ...
              'p_tc', 'qj', 10; 'p_limp', 'qj', 10; 'f_axial', 'qj', 10};
% common-cause and zonal items: [cause, design feature, why the independent product of sf_fta still holds or the
% beta term that covers it] (EN, TR)
in.ft.ccf = { ...
  'Propeller strike (ground or object)', 'Pervane çarpması (yer veya cisim)', ...
  'A strike is a load case of its own (the strike load with the propeller maker, 3.9); the tube anchors carry axial load only, so the tube carries no torque (it had no torsion check in 2.5 and needs none); post-strike inspection in the ICA (ICA-08)', ...
  'Çarpma kendi başına bir yük durumu (çarpma yükü pervane üreticisiyle, 3.9); tüp bağlantıları yalnız eksenel yük taşır, tüp tork taşımaz (2.5''te burulma kontrolü yoktu, gerekmiyor); çarpma sonrası muayene KTT''de (ICA-08)', ...
  'A strike loads the primary path in torsion and bending; the tube is not loaded in torsion and is inspected after the strike before flight, so a strike does not fail both paths in one flight', ...
  'Çarpma birincil yolu burulma ve eğilmede yükler; tüp burulmada yüklenmez ve çarpmadan sonra uçuştan önce muayene edilir, yani çarpma bir uçuşta iki yolu birden bozmaz'; ...
  'Blade-off imbalance', 'Pala kopması dengesizliği', ...
  'Propeller type design (CS-P) item; imbalance load TBD, new ICD row ICD-35 (owner: propeller maker); RGB mounts, shaft and tube checked at that load in 3.9', ...
  'Pervane tip tasarımı (CS-P) maddesi; dengesizlik yükü TBD, yeni ICD satırı ICD-35 (sahibi: pervane üreticisi); RGB bağlantıları, mil ve tüp 3.9''da bu yükle kontrol edilir', ...
  'Open until ICD-35 gives the load: the product holds only if the tube and the primary path are both shown at the imbalance load', ...
  'ICD-35 yükü verene kadar açık: çarpım, tüp ve birincil yolun ikisi de dengesizlik yükünde gösterilirse geçerli'; ...
  'Nacelle fire', 'Motor bölmesi yangını', ...
  'D5: case fire resistant with oil flow; the retention parts P103, P114, P115, P116 are steel and titanium (no melting in 15 min); the retention path also contains the A357 case nose and mount flange (C3), whose fire capability is open until the D5 rework (batch 3)', ...
  'D5: gövde yağ akışıyla yangına dayanıklı; tutma parçaları P103, P114, P115, P116 çelik ve titanyum (15 dk içinde erimez); tutma yolunda A357 gövde burnu ve bağlantı flanşı da var (C3), yangın dayanımı D5 yeniden çalışmasına (3. paket) kadar açık', ...
  'The fire acts on C3 in both paths; C3 is a single item already, so the dual-path products are unchanged; C3 under fire open (D5)', ...
  'Yangın iki yolda da C3''e etki eder; C3 zaten tek madde, çift yol çarpımları değişmez; yangında C3 açık (D5)'; ...
  'Over-torque (LD-01) and PT seizure (LD-08, at least 0.22 s)', 'Aşırı tork (LD-01) ve PT sıkışması (LD-08, en az 0,22 s)', ...
  'Shafts: yield safety >= 1.97 at LD-08 and rupture safety >= 1.48 at 1.5 x limit (step 2.5); the nut and the housing are rated in 3.9; torque limiting by CTL-01; LD-08 covers a PT seizure of at least 0.22 s only, the internal jams are a separate load case (G4)', ...
  'Miller: LD-08''de akma emniyeti >= 1,97, 1,5 x sınır yükte kopma emniyeti >= 1,48 (adım 2.5); somun ve gövde 3.9''da; CTL-01 ile tork sınırlama; LD-08 yalnız en az 0,22 s''lik PT sıkışmasını kapsar, iç kilitlenmeler ayrı yük durumu (G4)', ...
  'The tube carries no torque, so a torque event cannot fail it with the shaft', ...
  'Tüp tork taşımaz, bu yüzden bir tork olayı onu mille birlikte bozamaz'; ...
  'Corrosion of the latent paths (Ti tube, lip)', 'Gizli yolların korozyonu (Ti tüp, dudak)', ...
  'Anodized Ti, sealant on faying surfaces (ENV-03); tube and lip inspected at each TBO (Airworthiness Limitations item, CS-E 510(e)(1))', ...
  'Anotlanmış Ti, temas yüzeylerinde sızdırmazlık (ENV-03); tüp ve dudak her TBO''da muayene (Uçuşa Elverişlilik Sınırlamaları maddesi, CS-E 510(e)(1))', ...
  'The primary path is 4340 with zinc-nickel and inspected by ET at TBO; corrosion of the standby path is its latent rate', ...
  'Birincil yol çinko-nikelli 4340 ve TBO''da ET ile muayene edilir; yedek yolun korozyonu onun gizli oranıdır'; ...
  'Total loss of oil (FMEA FM37, FM43-FM45, FM57, FM61)', 'Tüm yağın kaybı (FMEA FM37, FM43-FM45, FM57, FM61)', ...
  'The QJ1024 loses its lubrication but the lip does not depend on oil; positive thrust pushes in during the mist run (LUB-07); after the loss of pitch-oil pressure the counterweights feather the propeller and its drag pulls out, on a mist-fed QJ1024 in the run-down and a stopped one when feathered; the dependent share is in E7 (lambda_oil x p, p from sf_lip, TBR)', ...
